SELECT * FROM app_user WHERE username = #{username}
AND deleted_at IS NULL
ORDER BY id ASC LIMIT 1

SELECT EXISTS (
  SELECT 1
  FROM app_user
  WHERE username = #{username}

    AND deleted_at IS NULL

)

SELECT EXISTS (
  SELECT 1
  FROM app_user
  WHERE phone = #{phone}
    AND deleted_at IS NULL
)

SELECT EXISTS (
  SELECT 1
  FROM app_user
  WHERE email = #{email}
    AND deleted_at IS NULL
)

SELECT *
FROM app_user
WHERE 
ORDER BY display_name ASC, id ASC
OFFSET #{offset}
LIMIT #{limit}

SELECT * FROM app_user WHERE id IN
#{id}
ORDER BY id ASC
